/**
 * UI Assets embebidos directamente en Base64 Data URI.
 *
 * Ventajas:
 * 1. 0 peticiones HTTP: No pasan por el servidor de Next.js.
 * 2. Inmunes a 'must-revalidate' y al recolector de basura del HTTP cache al cambiar de ruta.
 * 3. Renderizado síncrono instantáneo (frame 0) sin parpadeos (flickering).
 */

export const BORDER_NORMAL_DATA_URI = "data:image/png;base64,";

export const LEGACY_ICON_DATA_URI = "data:image/png;base64,";

export const CHROMA_ICON_DATA_URI = "data:image/png;base64,";

export const RARITY_GEM_DATA_URIS: Record<string, string> = {
  "epic": "data:image/png;base64,",
  "exalted": "data:image/png;base64,",
  "legendary": "data:image/png;base64,",
  "mythic": "data:image/png;base64,",
  "transcendent": "data:image/png;base64,",
  "ultimate": "data:image/png;base64,",
};

export const MASTERY_FLAG_EMPTY_DATA_URI = "data:image/png;base64,"

export function getRarityGemUri(rarity: string | null | undefined): string | undefined {
  if (!rarity || rarity === "NoRarity") return undefined;
  const normalized =
    rarity === "Signature"
      ? "transcendent"
      : rarity === "Hall"
      ? "exalted"
      : rarity.toLowerCase();
  return RARITY_GEM_DATA_URIS[normalized];
}
